document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("milestoneModal");if(!t)return;const n=document.getElementById("milestoneModalLabel"),d=document.getElementById("milestoneModalBody");t.addEventListener("show.bs.modal",c=>{const e=c.relatedTarget;if(!e)return;const l=e.getAttribute("data-milestone-id"),r=l?document.getElementById(l)?.closest(".col"):e.closest(".col");if(!r)return;const o=r.cloneNode(!0);o.querySelector(".card-header")?.remove(),o.querySelectorAll("[id]").forEach(s=>s.removeAttribute("id")),n.textContent=e.textContent.trim()||"Milestone Details",d.replaceChildren(o)}),t.addEventListener("hidden.bs.modal",()=>{n.textContent="",d.replaceChildren()})});
